import{_ as a,o as t,c as n,a5 as r}from"./chunks/framework.pJebtgMf.js";const m=JSON.parse('{"title":"AI 动态 · 2026-08-20","description":"","frontmatter":{"title":"AI 动态 · 2026-08-20","date":"2026-08-20T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-20.md","filePath":"news/2026-08/ai-news-2026-08-20.md","lastUpdated":null}'),s={name:"news/2026-08/ai-news-2026-08-20.md"};function o(i,e,p,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-08-20" tabindex="-1">AI 动态 · 2026-08-20 <a class="header-anchor" href="#ai-动态-·-2026-08-20" aria-label="Permalink to &quot;AI 动态 · 2026-08-20&quot;">​</a></h1><blockquote><p>截至 2026-08-20。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="meta-ai-推出-mac-应用-支持跨应用听写和屏幕理解" tabindex="-1">Meta AI 推出 Mac 应用，支持跨应用听写和屏幕理解 <a class="header-anchor" href="#meta-ai-推出-mac-应用-支持跨应用听写和屏幕理解" aria-label="Permalink to &quot;Meta AI 推出 Mac 应用，支持跨应用听写和屏幕理解&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/ee662d8995c9.jpg" alt="配图"></p><p>Meta 发布了一款新的 Mac 应用，用户可以将窗口共享给 AI 聊天机器人，后者能根据屏幕内容提供建议、回答问题或生成内容。该应用还支持跨所有应用的听写功能，与 Wispr Flow、Superwhisper 等工具类似。此举是 Meta 将 AI 助手打造为生产力工具、与竞争对手桌面应用抗衡的一部分。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/20/meta-ais-new-mac-app-wants-you-to-talk-to-your-apps/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="binance-允许-ai-代理进行交易-但风险控制主要依赖用户" tabindex="-1">Binance 允许 AI 代理进行交易，但风险控制主要依赖用户 <a class="header-anchor" href="#binance-允许-ai-代理进行交易-但风险控制主要依赖用户" aria-label="Permalink to &quot;Binance 允许 AI 代理进行交易，但风险控制主要依赖用户&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/8bdea2b8e84c.jpg" alt="配图"></p><p>加密货币交易所 Binance 推出 Agent OS，允许 AI 代理执行交易操作，并支持与 ChatGPT、Claude Code、Cursor 等工具集成。然而，平台对 AI 代理的监控和风险控制机制有限，用户需自行承担潜在风险。这一举措引发了关于 AI 代理在金融领域安全性和监管的讨论。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/20/binance-now-lets-ai-agents-trade-but-keeping-them-in-check-is-largely-up-to-users/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="stripe-收购-openrouter-的真实动机-支付基础设施而非-奇点" tabindex="-1">Stripe 收购 OpenRouter 的真实动机：支付基础设施而非“奇点” <a class="header-anchor" href="#stripe-收购-openrouter-的真实动机-支付基础设施而非-奇点" aria-label="Permalink to &quot;Stripe 收购 OpenRouter 的真实动机：支付基础设施而非“奇点”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/f6c8452b409b.jpg" alt="配图"></p><p>支付巨头 Stripe 收购了 AI 模型路由初创公司 OpenRouter，官方宣称是为了迎接“奇点”，但分析认为真实原因在于 OpenRouter 的支付处理需求。OpenRouter 作为 AI 模型聚合平台，每年处理大量 API 调用和账单，Stripe 可借此巩固其在 AI 经济中的支付基础设施地位。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/19/stripe-didnt-really-buy-openrouter-because-of-the-singularity/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai-与-anthropic-展开企业数据隐私保护竞赛" tabindex="-1">OpenAI 与 Anthropic 展开企业数据隐私保护竞赛 <a class="header-anchor" href="#openai-与-anthropic-展开企业数据隐私保护竞赛" aria-label="Permalink to &quot;OpenAI 与 Anthropic 展开企业数据隐私保护竞赛&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/c09e10e34a30.jpg" alt="配图"></p><p>OpenAI 和 Anthropic 正在竞争为企业客户提供更强大的数据隐私保护。OpenAI 推出了零数据保留和私有安全处理等新措施，而 Anthropic 则强调其隐私承诺。这场竞赛反映了企业客户对 AI 服务数据安全的高度重视，也推动了两家公司不断提升隐私标准。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/19/openai-seeks-to-one-up-anthropic-with-new-customer-privacy-protections/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="openai-推出-ai-futures-博客-探讨变革性-ai-的社会影响" tabindex="-1">OpenAI 推出 AI Futures 博客，探讨变革性 AI 的社会影响 <a class="header-anchor" href="#openai-推出-ai-futures-博客-探讨变革性-ai-的社会影响" aria-label="Permalink to &quot;OpenAI 推出 AI Futures 博客，探讨变革性 AI 的社会影响&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/4ef7b332fe84.png" alt="配图"></p><p>OpenAI 宣布推出新博客 AI Futures，由新成立的 Strategic Futures 团队运营，旨在探讨变革性 AI 如何重塑权力、治理、经济和个人自由。该博客将发表作者个人观点，不代表 OpenAI 官方立场。首篇文章由 Dean Ball 撰写，引用美国宪法观点，提出自由社会应如何应对 AI 权力扩张的问题。</p><p class="news-entry-source"><a href="https://openai.com/index/introducing-ai-futures" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="stampli-借助-chatgpt-work-和-codex-将上线时间缩短-68" tabindex="-1">Stampli 借助 ChatGPT Work 和 Codex 将上线时间缩短 68% <a class="header-anchor" href="#stampli-借助-chatgpt-work-和-codex-将上线时间缩短-68" aria-label="Permalink to &quot;Stampli 借助 ChatGPT Work 和 Codex 将上线时间缩短 68%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/7f3cbd8e69b7.png" alt="配图"></p><p>金融科技公司 Stampli 在固定截止日期和设计资源受限的情况下，使用 OpenAI 的 Codex 和 ChatGPT Work 将原本需要数周的上线准备工作压缩至数天。该公司每周使用 ChatGPT Work 创建数百条内容，并通过 Codex 实现了 3.16 倍的上线速度提升。这一案例展示了 AI 工具在真实业务场景中的效率价值。</p><p class="news-entry-source"><a href="https://openai.com/index/stampli" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="greg-brockman-在-openai-内部权力日益集中" tabindex="-1">Greg Brockman 在 OpenAI 内部权力日益集中 <a class="header-anchor" href="#greg-brockman-在-openai-内部权力日益集中" aria-label="Permalink to &quot;Greg Brockman 在 OpenAI 内部权力日益集中&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/843d98b6ba74.jpg" alt="配图"></p><p>在 OpenAI 经历一系列高管离职和外部挑战后，联合创始人兼总裁 Greg Brockman 悄然积累了更多权力。他自公司成立以来一直担任核心工程角色，如今在战略决策中影响力更大。随着 OpenAI 准备 IPO，Brockman 的领导地位对公司的稳定和发展至关重要。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/982774/greg-brockman-openai-role-expansion" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="slack-推出协作式-vibe-coding-频道-支持-ai-代理共同开发" tabindex="-1">Slack 推出协作式 vibe-coding 频道，支持 AI 代理共同开发 <a class="header-anchor" href="#slack-推出协作式-vibe-coding-频道-支持-ai-代理共同开发" aria-label="Permalink to &quot;Slack 推出协作式 vibe-coding 频道，支持 AI 代理共同开发&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/eb41be3359f4.jpg" alt="配图"></p><p>Slack 发布 Slack Code 功能，引入专门的代码频道，团队可在其中与 AI 代理（如 Anthropic 的 Claude 或 Cognition 的 Devin）协作进行 vibe-coding。该功能支持项目特定的代码频道、变更对比和 HTML 预览，旨在减少团队在不同工具间的切换，提升开发协作效率。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/982628/slack-code-vibe-coding-channels-launch" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="美图影像研究院提出场景文本编辑新方案-支持多语言无痕修改" tabindex="-1">美图影像研究院提出场景文本编辑新方案，支持多语言无痕修改 <a class="header-anchor" href="#美图影像研究院提出场景文本编辑新方案-支持多语言无痕修改" aria-label="Permalink to &quot;美图影像研究院提出场景文本编辑新方案，支持多语言无痕修改&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/c9d64fe55a3d.png" alt="配图"></p><p>美图影像研究院（MT Lab）提出一种面向开放词汇的自提示场景文本编辑方法，可直接从输入图像提取字体风格并生成字形提示，实现端到端高保真文字替换。该方法无需 OCR 或固定字表，支持中文和小语种，避免了图像修补失真问题。相关成果被 ICML 2026 录用。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/PuaPuRIjd35ItQSVCOK1?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="vivo-提出知识驱动计算-kdc-长期运行主张-保存历史不等于形成记忆" tabindex="-1">vivo 提出知识驱动计算（KDC）长期运行主张：保存历史不等于形成记忆 <a class="header-anchor" href="#vivo-提出知识驱动计算-kdc-长期运行主张-保存历史不等于形成记忆" aria-label="Permalink to &quot;vivo 提出知识驱动计算（KDC）长期运行主张：保存历史不等于形成记忆&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/b5ebab32d692.png" alt="配图"></p><p>vivo 研究员肖博在 InfoQ 发表文章，提出记忆的生命周期模型，包括形成、强化、衰减、冲突、遗忘、迁移和归档。文章强调记忆的价值在于选择性影响未来决策，而非无差别保存历史，并指出反馈验证与错误归因是系统自修正的关键机制。这是 KDC 系列第四篇。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/EF97eR5oivR50UqIINsP?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="colossal-ai-分拆公司估值-38-亿美元-首个模型瞄准抗衰老" tabindex="-1">Colossal AI 分拆公司估值 38 亿美元，首个模型瞄准抗衰老 <a class="header-anchor" href="#colossal-ai-分拆公司估值-38-亿美元-首个模型瞄准抗衰老" aria-label="Permalink to &quot;Colossal AI 分拆公司估值 38 亿美元，首个模型瞄准抗衰老&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Dallas News</span><time datetime="2026-08-20">2026-08-20</time></p><p>Colossal AI 的分拆公司以 38 亿美元估值融资，并推出首个模型，专注于抗衰老领域。这表明 AI 在生物技术和健康领域的应用前景广阔，吸引了大量投资。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMitwFBVV95cUxQb3VtcVhtQ21oZ0tDeUx1SEJBX1dYWGVGdEpidGVVWGhTYWJlQXJpc2hVVW1MMktldVlzMVlIZzFieXg4RVhhYjF1ekVXWThTMTY0enh6ejNrZTlGeFhYRTNITG1BVGMzS0xWSE10WGFaaDhha25QeEVOOTVadXNDSG9xQWV0ZWtycUNIRFlYa2tEU25GbmZhTHZXVjE5NHlVaDJIZ3VKbzJQVUl0UWlrdS03OU9CWFE?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="sanja-fidler-的世界模型初创公司-veeda-ai-获-9000-万美元种子融资" tabindex="-1">Sanja Fidler 的世界模型初创公司 Veeda AI 获 9000 万美元种子融资 <a class="header-anchor" href="#sanja-fidler-的世界模型初创公司-veeda-ai-获-9000-万美元种子融资" aria-label="Permalink to &quot;Sanja Fidler 的世界模型初创公司 Veeda AI 获 9000 万美元种子融资&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">SiliconANGLE</span><time datetime="2026-08-20">2026-08-20</time></p><p>由 AI 研究员 Sanja Fidler 创立的世界模型初创公司 Veeda AI 在种子轮融资中筹集了 9000 万美元。该公司专注于开发世界模型，这可能对机器人、自动驾驶和模拟等领域产生重要影响。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMiqgFBVV95cUxOZUpET2g2MTNFVnVnRVY3U2hob2UwcnpTYnhOQVJ2RDdFQW4zTHI2LThnelJwZV9CTUh6U1J0WlJOdkRGVnM1MVVQQ1hST281VHdXWV9BekdXQ2lFdWwycGQta1N1X3RTS25YNnh3em9RT0ZZVE14TUJTOUZjRHNzM0tlU2lya0F0VHFLdDcwTG9LaUtvZFVyaXEzaHZySGRqb19EbldTNVpGQQ?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="openlogi-用-rust-编写的-logitech-options-本地替代品" tabindex="-1">OpenLogi：用 Rust 编写的 Logitech Options+ 本地替代品 <a class="header-anchor" href="#openlogi-用-rust-编写的-logitech-options-本地替代品" aria-label="Permalink to &quot;OpenLogi：用 Rust 编写的 Logitech Options+ 本地替代品&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">AprilNEA/OpenLogi</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/118dd7157e65.png" alt="配图"></p><p>OpenLogi 是一个用 Rust 编写的原生、本地优先的 Logitech Options+ 替代品，支持通过 HID++ 重新映射按钮、调整 DPI 和 SmartShift。无需账户，无遥测，注重隐私。对于希望自定义罗技设备的用户来说，这是一个开源的选择。</p><p class="news-entry-source"><a href="https://github.com/AprilNEA/OpenLogi" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="moneyprinterturbo-一键生成高清短视频的-ai-工具" tabindex="-1">MoneyPrinterTurbo：一键生成高清短视频的 AI 工具 <a class="header-anchor" href="#moneyprinterturbo-一键生成高清短视频的-ai-工具" aria-label="Permalink to &quot;MoneyPrinterTurbo：一键生成高清短视频的 AI 工具&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">harry0703/MoneyPrinterTurbo</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/2c1dc4618b68.png" alt="配图"></p><p>MoneyPrinterTurbo 是一个开源项目，利用 AI 大模型和自动化工作流，根据主题或关键词一键生成高清短视频。它简化了视频制作流程，适合内容创作者和营销人员快速生成视频内容。</p><p class="news-entry-source"><a href="https://github.com/harry0703/MoneyPrinterTurbo" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="agent-substrate-核心系统开源" tabindex="-1">Agent Substrate：核心系统开源 <a class="header-anchor" href="#agent-substrate-核心系统开源" aria-label="Permalink to &quot;Agent Substrate：核心系统开源&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">agent-substrate/substrate</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/5bdeef670531.png" alt="配图"></p><p>Agent Substrate 的核心系统已在 GitHub 上开源。该项目旨在提供 AI 智能体的基础设施，可能包括调度、身份和生命周期管理等功能。对于构建复杂 AI 代理系统的开发者来说，这是一个值得关注的资源。</p><p class="news-entry-source"><a href="https://github.com/agent-substrate/substrate" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="posthog-面向自驱产品的开发者工具平台" tabindex="-1">PostHog：面向自驱产品的开发者工具平台 <a class="header-anchor" href="#posthog-面向自驱产品的开发者工具平台" aria-label="Permalink to &quot;PostHog：面向自驱产品的开发者工具平台&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">PostHog/posthog</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/3140a1b3d556.png" alt="配图"></p><p>PostHog 是一个开源平台，提供 AI 可观测性、分析、会话回放、功能开关、实验、错误跟踪和日志等工具，旨在捕获代理诊断问题所需的所有上下文。它帮助团队构建“自动驾驶”产品，通过数据驱动决策。</p><p class="news-entry-source"><a href="https://github.com/PostHog/posthog" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github-copilot-应用教程-使用-我的工作-窗格管理任务" tabindex="-1">GitHub Copilot 应用教程：使用“我的工作”窗格管理任务 <a class="header-anchor" href="#github-copilot-应用教程-使用-我的工作-窗格管理任务" aria-label="Permalink to &quot;GitHub Copilot 应用教程：使用“我的工作”窗格管理任务&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/a82fa01d43fb.png" alt="配图"></p><p>GitHub 发布 Copilot 应用初学者指南，介绍如何使用“我的工作”窗格跟踪多个 Copilot 会话中的进行中、已完成和下一步任务。该功能帮助开发者更好地组织 AI 辅助编码工作，提高效率。</p><p class="news-entry-source"><a href="https://github.blog/ai-and-ml/github-copilot/github-copilot-app-for-beginners-managing-your-work/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="buildpacks-将容器加固控制点从-dockerfile-中移出" tabindex="-1">Buildpacks 将容器加固控制点从 Dockerfile 中移出 <a class="header-anchor" href="#buildpacks-将容器加固控制点从-dockerfile-中移出" aria-label="Permalink to &quot;Buildpacks 将容器加固控制点从 Dockerfile 中移出&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-20">2026-08-20</time></p><p>Cloud Native Buildpacks 项目从 CNCF 毕业，其方法将容器构建最佳实践集中于平台工程团队，而非各应用团队。通过使用构建器和运行镜像，Buildpacks 允许在不重建应用层的情况下进行基础镜像更新，从而更快修复 CVE 漏洞。这改变了 Dockerfile 中 FROM 语句的声明方式，提升了安全补丁的部署效率。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/8EPJjIlk5WwgiXphjxEW?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="将可理解性作为架构特性-无法理解的系统无法安全演进" tabindex="-1">将可理解性作为架构特性：无法理解的系统无法安全演进 <a class="header-anchor" href="#将可理解性作为架构特性-无法理解的系统无法安全演进" aria-label="Permalink to &quot;将可理解性作为架构特性：无法理解的系统无法安全演进&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-20">2026-08-20</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/3e95dcc1c3f3.jpg" alt="配图"></p><p>InfoQ 文章探讨了演进式架构中可理解性的重要性。作者认为，团队成员需要深刻理解系统背后的“理论”才能安全演进。文章引入认知债务和意图债务概念，指出系统不仅包含代码，还包含团队对系统的共同理解。缺乏可理解性会导致系统难以维护和演进。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/d5mWBGZxB2l2vRTO8wFU?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="nvidia-考虑投资-ai-数据提供商-mercor-估值-200-亿美元" tabindex="-1">Nvidia 考虑投资 AI 数据提供商 Mercor，估值 200 亿美元 <a class="header-anchor" href="#nvidia-考虑投资-ai-数据提供商-mercor-估值-200-亿美元" aria-label="Permalink to &quot;Nvidia 考虑投资 AI 数据提供商 Mercor，估值 200 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Yahoo Finance</span><time datetime="2026-08-20">2026-08-20</time></p><p>据报道，Nvidia 正在探索对 AI 数据提供商 Mercor 的投资，估值可能达到 200 亿美元。Mercor 帮助 Nvidia 开发开源模型，此次投资将加强双方合作，并巩固 Nvidia 在 AI 数据供应链中的地位。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMioAFBVV95cUxQQUs2Ym1JVWo5UlBZMWt0SWFpS3J0M25mYktiTXRyT1FEeDNYeXRpLTl4amE1UTNCSEtMRVU4RVV4OHpEdmFMNEs1MU8wMGpUVndMbG5QWDkxMVppZ2pMZ1JETW45dUZ1QXdKTjZjZWhHbzdWbHdmLTdiOHlmakp6TGU5VkQ3bHltZFAweV8xT3F0QnMwOWkzVF9fTks4Y09O?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const u=a(s,[["render",o]]);export{m as __pageData,u as default};
